{
  "positionId": "P05",
  "interviews": [
    {
      "categoryId": "P05-C2",
      "itemId": "P05-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "광고 반응 분석에서 얻은 결론을 타깃, 메시지, 채널, 일정이 있는 실행 계획으로 구체화하고 이해관계자와 합의해 집행으로 연결했는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "꽃집 인스타그램 광고에서 게시물 유형별 반응을 비교하고 광고 집행 방향을 정해야 했던 상황을 설명한다.",
          "task": "분석 결론을 실제 집행 가능한 계획으로 바꾸기 위해 본인이 담당한 범위를 설명한다.",
          "action": "분석 결론을 바탕으로 타깃, 메시지, 채널, 일정을 구체화하고 꽃집 사장님과 실행 내용을 합의한 방식을 설명한다.",
          "result": "합의한 계획이 실제 광고 집행에 반영되었는지와 계획 대비 실행 여부를 확인할 수 있는 내용을 설명한다."
        },
        "expectedEvidence": [
          "게시물 유형별 반응에 대한 분석 결론과 실행 계획 사이의 연결 근거",
          "타깃, 메시지, 채널, 일정으로 구체화된 실행 계획",
          "꽃집 사장님과 실행 내용을 공유하고 합의한 구체적인 행동",
          "본인이 수행한 작업과 계획이 실제 집행에 반영된 근거"
        ]
      },
      "question": "동네 꽃집 인스타그램 광고 소액 집행 분석에서, 분석 결론을 실제 광고 집행 계획으로 구체화한 방식은 무엇이었나요?",
      "answerTip": "당시의 한 장면을 골라 본인이 한 일을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "분석 결론이 실행 계획에 어떻게 반영되었는지 구체적으로 설명한다.",
            "타깃, 메시지, 채널, 일정이 확인되며 각 계획이 분석 결론과 연결된다.",
            "사장님과 실행 내용을 합의한 행동과 본인이 맡은 집행 범위를 설명하고 실제 반영 여부를 제시한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "분석 결론을 광고 집행 내용으로 옮긴 연결은 확인되지만 타깃, 메시지, 채널, 일정 중 일부가 불명확하다.",
            "본인의 실행 행동은 확인되지만 이해관계자와의 합의 또는 계획의 실제 반영 여부에 대한 설명이 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "분석 결과나 광고 성과만 제시하고 이를 실행 계획으로 구체화한 근거를 설명하지 못한다.",
            "실행 계획, 이해관계자와의 합의, 본인의 집행 행동을 확인할 구체적인 근거가 부족하다."
          ]
        }
      }
    },
    {
      "categoryId": "P05-C2",
      "itemId": "P05-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "캠페인의 성과를 판단할 지표를 정하고 결과를 해석해 효과가 있었던 요소와 바꿔야 할 내용을 개선안으로 보고할 수 있는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "꽃집 인스타그램 광고의 게시물 유형별 클릭과 문의 DM 수를 비교하고 결과를 사장님께 설명했던 상황을 설명한다.",
          "task": "광고의 효과를 판단할 성과 지표를 정하고 그 결과를 개선 방향과 함께 전달해야 했던 본인의 역할을 설명한다.",
          "action": "성과 지표를 선택한 이유, 게시물 유형별 결과의 해석, 그 해석을 바탕으로 사장님께 전달한 개선 내용을 설명한다.",
          "result": "사장님께 전달된 효과 판단과 개선 방향이 무엇이었는지 설명하며, 후속 집행 결과가 있다면 최초 판단과 구분해 제시한다."
        },
        "expectedEvidence": [
          "광고 성과 판단에 사용한 지표와 해당 지표를 선택한 이유",
          "게시물 유형별 지표 비교에 근거한 효과 해석",
          "성과 해석과 변경할 광고 내용 사이의 논리적 연결",
          "효과가 있었던 요소와 개선 방향을 사장님께 전달한 구체적인 내용"
        ]
      },
      "question": "꽃집 인스타그램 광고의 결과를 사장님께 말로 설명했을 때, 게시물 유형별 광고 효과를 판단한 근거는 무엇이었나요?",
      "answerTip": "기억나는 내용을 차분하게 정리하고 아는 범위에서 답해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "성과 지표와 선택 이유를 설명하고 게시물 유형별 비교 결과를 구체적으로 제시한다.",
            "지표에 근거해 효과가 있었던 요소를 해석하고 바꿔야 할 광고 내용으로 연결한다.",
            "사장님께 전달한 효과 판단과 개선 방향이 구체적으로 확인되며 구두 설명도 보고 근거로 인정한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "성과 지표와 비교 결과를 바탕으로 효과 또는 개선 방향을 설명하지만 지표 선택 이유나 해석의 구체성이 부족하다.",
            "개선 방향은 결과와 연결되지만 사장님께 실제 전달한 내용이 일부만 확인된다."
          ]
        },
        "poor": {
          "criteria": [
            "광고 성과가 좋아졌다는 진술만 있고 지표 선택이나 비교에 근거한 효과 해석이 없다.",
            "성과 해석과 개선 방향의 연결이 없거나 사장님께 전달한 내용을 확인할 근거가 부족하다."
          ]
        }
      }
    }
  ]
}
